function expandCurriculum(workspace) {
  expandPrinciples(workspace);
  for (const course of workspace.courses) {
    if (course.curriculumEdition >= 1) continue;
    const existing = new Set(course.topics.map(t => t.id));
    for (const [courseIds, ...args] of courseUnits) {
      if (!courseIds.includes(course.id)) continue;
      const topic = lesson(...args);
      topic.choices = [...topic.choices];
      if (!existing.has(topic.id)) course.topics.push(topic);
    }
    course.curriculumEdition = 1;
  }
  return workspace;
}

